int k7npu_main(int argc, char **argv);
static unsigned int reads;
static unsigned int core_reads;
static uintptr_t bad_addr;
static uint32_t bad_value;

uint32_t k7npu_read32(uintptr_t address)
{
  reads++;
  if (address >= 0x27700000 && address < 0x27710000)
    {
      uintptr_t offset = (address - 0x27700000) & 0x7fff;
      assert(offset == 0 || offset == 4 || offset == 0x28 ||
             offset == 0x48 || offset == 0x2004 || offset == 0x2104);
      core_reads++;
      return 0;
    }
  assert((address >= 0x27200870 && address <= 0x27200a80) ||
         address == 0x27380230 || address == 0x27380570 ||
         address == 0x27380128 || address == 0x27380120);
  if (address == bad_addr) return bad_value;
  if (address == 0x27380570) return 0x01c00000;
  return 0;
}

static void run(const char *mode, unsigned int count, int status)
{
  char *args[] = {"k7npu", (char *)mode};
  reads = core_reads = 0;
  assert(k7npu_main(2, args) == status);
  assert(core_reads == count);
}

int main(void)
{
  static const struct {uintptr_t address; uint32_t value;} denied[] =
  {
    {0x27380230, 1},
    {0x27380570, 0x01800000}, {0x27380570, 0x01400000},
    {0x27380570, 0x00c00000},
