    {0x27200870, 0x200}, {0x27200874, 1},
    {0x2720087c, 0x10}, {0x2720087c, 0x20},
    {0x27200880, 1}, {0x27200880, 0x1000},
    {0x27200a70, 0x200}, {0x27200a74, 1},
    {0x27200a7c, 2}, {0x27200a80, 1},
  };
  unsigned int i;
  run("invalid", 0, 1);
  assert(reads == 0);
  run("status", 0, 0);
  assert(reads == 12);
  run("probe", 12, 0);
  for (i=0; i<sizeof(denied)/sizeof(denied[0]); i++)
    {
      bad_addr = denied[i].address;
      bad_value = denied[i].value;
      run("probe", 0, 1);
    }
  puts("PASS: probe blocks unsafe prerequisites; fixed read-only allowlist");
  return 0;
}
