#include <nuttx/config.h>
#include <nuttx/cache.h>
#include <errno.h>
#include <inttypes.h>
#include <stdint.h>
#include <stdio.h>
#include <time.h>
#include "rk3576_npu_mmu.h"
#include "rk3576_npu_window.h"
#include "k7npu_fixture_io.h"

